class Solution:
    def reorganizeStringSmallest(self, s: str) -> str:
        from collections import Counter
        from functools import lru_cache
        chars = tuple(sorted(set(s)))
        start = tuple(Counter(s).get(ch, 0) for ch in chars)
        def feasible(counts, prev):
            total = sum(counts)
            for i, c in enumerate(counts):
                limit = total // 2 if chars[i] == prev else (total + 1) // 2
                if c > limit:
                    return False
            return True
        if not feasible(start, ''):
            return ""
        @lru_cache(None)
        def dfs(counts, prev):
            if sum(counts) == 0:
                return ""
            for i, ch in enumerate(chars):
                if counts[i] and ch != prev:
                    nxt = list(counts)
                    nxt[i] -= 1
                    nxt = tuple(nxt)
                    if feasible(nxt, ch):
                        tail = dfs(nxt, ch)
                        if tail is not None:
                            return ch + tail
            return None
        return dfs(start, '') or ""

