class Solution:
    def reorganizeStringSmallest(self, s: str) -> str:
        from collections import Counter
        counts = Counter(s)
        chars = sorted(counts)
        def feasible(prev):
            total = sum(counts.values())
            for ch in chars:
                limit = total // 2 if ch == prev else (total + 1) // 2
                if counts[ch] > limit:
                    return False
            return True
        if not feasible(''):
            return ""
        ans = []
        prev = ''
        for _ in range(len(s)):
            for ch in chars:
                if counts[ch] == 0 or ch == prev:
                    continue
                counts[ch] -= 1
                if feasible(ch):
                    ans.append(ch)
                    prev = ch
                    break
                counts[ch] += 1
            else:
                return ""
        return ''.join(ans)

