class Solution:
    def reorganizeStringSmallest(self, s: str) -> str:
        from collections import Counter
        import heapq
        counts = Counter(s)
        chars = sorted(counts)
        def feasible(prev):
            total = sum(counts.values())
            for ch in chars:
                limit = total // 2 if ch == prev else (total + 1) // 2
                if counts[ch] > limit:
                    return False
            return True
        if not feasible(''):
            return ""
        heap = chars[:]
        heapq.heapify(heap)
        ans = []
        prev = ''
        for _ in range(len(s)):
            skipped = []
            placed = None
            while heap:
                ch = heapq.heappop(heap)
                if counts[ch] == 0:
                    continue
                if ch == prev:
                    skipped.append(ch)
                    continue
                counts[ch] -= 1
                if feasible(ch):
                    placed = ch
                    break
                counts[ch] += 1
                skipped.append(ch)
            for ch in skipped:
                heapq.heappush(heap, ch)
            if placed is None:
                return ""
            ans.append(placed)
            prev = placed
            if counts[placed] > 0:
                heapq.heappush(heap, placed)
        return ''.join(ans)

